// resolveSourceBaseURL picks the GitHub base URL the syncer composes its
// source-fetch URL against. Defaults to https://github.com so production
// behaviour is unchanged; ENTIRE_GITHUB_BASE_URL=http://mockgithub:9001
// (or similar) repoints the fetch path at a mock for load testing.
// A single trailing slash is stripped so the syncer's "%s/%s/%s" format
// doesn't produce a double slash.
func resolveSourceBaseURL(getenv func(string) string) string {
	raw := getenv("ENTIRE_GITHUB_BASE_URL")
	if raw == "" {
		return "https://github.com"
	}
	return strings.TrimSuffix(raw, "/")
}
